def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Data is too short to remove two bytes")
    return int.from_bytes(self.data[-2:], byteorder='big', signed=False)

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop two bytes")
    data = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(data, 'big')

