def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, with ties going to the nearest even number.

    Args:
    n (float): The number to round.

    Returns:
    int: The rounded integer.
    """
    if n % 2 != 0 and n - math.floor(n) == 0.5:
        return math.floor(n + 1)
    else:
        return round(n)

def round_half_to_even(n):
    from math import floor, ceil, copysign

    if n.is_integer():
        return int(n)

    floor_part, decimal_part = divmod(abs(n), 1)
    sign = copysign(1, n)

    if floor_part % 2 == 0 and decimal_part >= 0.5:
        return sign * (floor_part + 1)
    elif floor_part % 2 != 0 and decimal_part >= 0.5:
        return sign * floor_part
    else:
        return sign * floor_part

