def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass."""
    class Point:
        __slots__ = ('wkt',)
        def __init__(self, wkt):
            self.wkt = wkt

        def __repr__(self):
            return "Point(%s)" % self.wkt

    for field_name, field_type in fields.items():
        setattr(Point, field_name, field_type)

    point_type_func = types.new_class(name, (Point,), {})

    for field_name, field_type in fields.items():
        setattr(point_type_func, field_name, types.new_class(field_name, (), {}))

    # set the SRID map
    point_type_func.SRID_MAP = srid_map

    return point_type_func

