def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def wrapper(func):
        cache = {}

        def wrapper_inner(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key in cache:
                value = cache[key]
                if timer(value) < timer():
                    # Key is still valid, return the cached value
                    return value[0]
            else:
                # Key is not in cache, call the function
                result = func(*args, **kwargs)
                # Cache the result with its TTL
                cache[key] = (result, timer() + ttl if ttl else None)
            return result

        wrapper_inner.cache = cache
        return wrapper_inner

    return wrapper

class TTLCache:
    def __init__(self, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.ttl_items = OrderedDict()

    def __call__(self, func):
        def wrapper(*args, **kwargs):
            key = self._make_key(args, kwargs)
            if key in self.ttl_items:
                if self._is_stale(key):
                    del self.ttl_items[key]
                else:
                    return self.ttl_items[key]
            value = func(*args, **kwargs)
            self._update_cache(key, value)
            return value

        return wrapper

    def _make_key(self, args, kwargs):
        key = tuple(args) + tuple(sorted(iter(kwargs.items())))
        return key

    def _is_stale(self, key):
        if key in self.ttl_items:
            timestamp, value = self.ttl_items[key]
            return timestamp + self.ttl <= self.timer()

    def _update_cache(self, key, value):
        self.ttl_items[key] = (self.timer(), value)
        if len(self.ttl_items) > self.maxsize:
            self.ttl_items.popitem(last=False)

