    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, supp,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    number = None
    suppl = None
    values = []
    splstr = ""
    for c in issue:
        if c.isdigit():
            if c != "1" and c != "2":
                splstr += c
            else:
                suppl = splstr
                splstr = ""
        elif c == "{" or c == "}":
            if number:
                values.append(number)
            if suppl:
                values.append(suppl)
            number = None
            suppl = None
            splstr = ""
        elif c == ",":
            if number:
                values.append(number)
            if suppl:
                values.append(suppl)
            number = None
            suppl = None
            splstr = ""
        elif c == " ":
            if number:
                values.append(number)
            if suppl:
                values.append(suppl)
            number = None
            suppl = None
            splstr = ""
        else:
            if c.isalpha():
                number += c
            else:
                if number:
                    values.append(number)
                number = None
                suppl = None
                splstr = ""
    if number:
        values.append(number)
    if suppl:
        values.append(suppl)
    return values

