def deep_merge_nodes(nodes):
    processed = []
    in_process = []

    for key, value in nodes:
        if key in processed:
            if isinstance(processed[key], dict) and isinstance(value, dict):
                processed[key].update(value)
            else:
                processed[key] = value
        else:
            processed[key] = value

        in_process.append(key)

    for key in in_process:
        assert not key in processed, f'Key "{key}" was processed multiple times'

    return list(processed.items())

def deep_merge_nodes(nodes):
    merged = {}
    for key, value in nodes:
        if key in merged:
            if isinstance(merged[key], dict) and isinstance(value, dict):
                merged[key] = deep_merge_nodes((merged[key], value))
            else:
                if isinstance(merged[key], (int, str)):
                    merged[key] = value
        else:
            merged[key] = value
    return [((key, value), None) for key, value in merged.items()]

def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node_key, node_value in nodes:
        current_node = merged_nodes.get(node_key, node_value)
        while isinstance(current_node, dict):
            key = next(iter(current_node))
            if key in current_node:
                current_node = current_node[key]
            else:
