def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""

    with subprocess.Popen(['git', 'ls-files', '--', '-i', '--exclude-standard', '--exclude=".project"', '--exclude=".settings"', '--exclude=".pydev", "--exclude=".gitignore"]', '--only-matching'], stdout=subprocess.PIPE) as process:
        ignored_files = process.stdout.readlines()

    if not ignored_files:
        return ""

    ignored_files = [file.decode('utf-8').strip() for file in ignored_files]

    return ",".join(ignored_files)

def addignored(ignored):
    ignored_files = subprocess.check_output(['git', 'ls-files', '--pruned', '--exclude=new_files', '--exclude='.gitignore']).decode('utf-8').strip()
    ignored_list = ignored_files.split(',')
    ignored_list = [file.strip() for file in ignored_list if file not in ignored]
    ignored_list.sort()
    return ','.join(ignored_list)

