def _get_seq_with_type(seq, bufsize=None):
    '''Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    '''
    if bufsize is None:
        bufsize = sys.getsizeof(seq)
    try:
        istuple = isinstance(seq, tuple)
        if istuple or isinstance(seq, collections.abc.Sequence):
            if bufsize:
                tmp = seq[:bufsize] # large enough to get the type
                if isinstance(tmp, tuple):
                    seq = tuple(tmp)
                else:
                    seq = list(tmp)
            return seq, type(seq)
    except RecursionError:
        raise TypeError('Sequence is too large to analyze')

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, range):
        seq, length = seq.start, seq.stop - seq.start
        return range(seq, length), type(seq)
    elif isinstance(seq, (list, tuple)):
        return seq, type(seq)
    elif isinstance(seq, (str, bytes)):
        return seq.encode(), type(seq)
    elif seq is None:
        return [], type(seq)
    else:
        return seq, type(seq)

