class hist_to_graph:
    def __init__(self, hist: Histogram, make_value: Union[None, callable] = None, get_coordinate: str = "left", field_names: tuple = ("x", "y"), scale: Union[None, bool] = None):
        self.hist = hist
        self.make_value = make_value
        self.get_coordinate = get_coordinate
        self.field_names = field_names
        self.scale = scale

    def process(self) -> Graph:
        x_list = [None] * len(self.hist.values)
        if self.get_coordinate == "left":
            for i in range(len(self.hist.values)):
                x_list[i] = self.hist.labels[i]
        elif self.get_coordinate == "right":
            for i in range(len(self.hist.values)):
                x_list[i] = self.hist.labels[i] + self.hist.labels[i][1:]
        elif self.get_coordinate == "middle":
            for i in range(len(self.hist.values)):
                x_list[i] = self.hist.labels[i] + "middle"

        y_component = [self.make_value(bin_) for bin_ in self.hist.values if callable(self.make_value)]
        y_list = [v[0] for v in y_component]
        y_error_list = [v[1] for v in y_component]

        return Graph(x_list, y_list[:-1], y_error_list[:-1])

