def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def process_link(href, text):
        attributes = {'href': href, 'rel': 'noopener noreferrer'}
        for key, value in self.attributes:
            if value is not None:
                attributes[key] = value
        return self.template('\nlink{{action="external", type="click", attributes="{params}" style="text-decoration: underline; cursor: pointer;", text="{text}"}}', {'params': attributes, 'text': text})

